VALUES ('weiguo-r5', '靖伯', 'wei-weiguo', ARRAY[]::text[], '姬', '卫', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '疌伯之后，谥靖伯，西周时期卫国世君，承续姬姓卫国之嫡系，事见《史记》本国世家记载。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/卫靖伯"}]'::jsonb, '靖伯', NULL, '卫靖伯')
