VALUES ('weiguo-r6', '贞伯', 'wei-weiguo', ARRAY[]::text[], '姬', '卫', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '靖伯之后，谥贞伯，西周晚期卫国君主，在位约二十四年，事迹记载有限，事见《史记》本国世家记载。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/卫贞伯"}]'::jsonb, '贞伯', NULL, '卫贞伯')
