VALUES ('weiguo-r7', '顷侯', 'wei-weiguo', ARRAY[]::text[], '姬', '卫', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '贞伯之子，谥顷侯，曾遭戎狄侵扰，卫国在西周晚期国势一度不振，事见《史记》本国世家记载。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/卫顷侯"}]'::jsonb, '顷侯', NULL, '卫顷侯')
