VALUES ('weiguo-r8', '釐侯', 'wei-weiguo', ARRAY[]::text[], '姬', '卫', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '顷侯之子，谥釐侯，在位四十余年，为春秋以前卫国在位时间较长之君，事见《史记》本国世家记载。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/卫釐侯"}]'::jsonb, '釐侯', NULL, '卫釐侯')
