VALUES ('weiguo-r9', '余', 'wei-weiguo', ARRAY[]::text[], '姬', '卫', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '釐侯之子余，谥共伯，在位仅一年即为弟武公和所弑，卫国再度因篡弑更迭，事见《史记》本国世家记载。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/卫共伯"}]'::jsonb, '共伯', NULL, '卫共伯')
