VALUES ('weiguo-r11', '扬', 'wei-weiguo', ARRAY[]::text[], '姬', '卫', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '武公之子扬，谥庄公，宠妾生子州吁，好兵使将，石碏谏不听，乱端由此酝酿，事见《史记》本国世家记载。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/卫庄公"}]'::jsonb, '庄公', NULL, '卫庄公')
