VALUES ('weiguo-r12', '完', 'wei-weiguo', ARRAY[]::text[], '姬', '卫', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '庄公嫡子完，谥桓公，州吁骄奢被绌而出奔，前719年为州吁袭杀，在位十五年，事见《史记》本国世家记载。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/卫桓公"}]'::jsonb, '桓公', NULL, '卫桓公')
