VALUES ('weiguo-r13', '州吁', 'wei-weiguo', ARRAY[]::text[], '姬', '卫', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '庄公庶子州吁，好兵弑兄自立，联合宋、陈、蔡伐郑，旋即为石碏诱杀于濮，在位仅数月。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/州吁"}]'::jsonb, NULL, NULL, '州吁')
