VALUES ('weiguo-r15', '朔', 'wei-weiguo', ARRAY[]::text[], '姬', '卫', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '宣公之子朔，谥惠公，宣公杀急子后立之，一度出奔，赖齐复位，前后两段子在位，事见《史记》本国世家记载。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/卫惠公"}]'::jsonb, '惠公', NULL, '卫惠公')
