VALUES ('weiguo-r16', '黔牟', 'wei-weiguo', ARRAY[]::text[], '姬', '卫', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '惠公出奔期间，周平王立弟黔牟，在位八年，惠公赖齐复位后，黔牟出奔周，事见《史记》本国世家记载。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/黔牟"}]'::jsonb, NULL, NULL, '黔牟')
