VALUES ('weiguo-r18', '赤', 'wei-weiguo', ARRAY[]::text[], '姬', '卫', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '惠公之子赤，谥懿公，好鹤淫乐、不修政理，前660年狄人攻卫，懿公兵败被杀，事见《史记》本国世家记载。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/卫懿公"}]'::jsonb, '懿公', NULL, '卫懿公')
