VALUES ('weiguo-r19', '申', 'wei-weiguo', ARRAY[]::text[], '姬', '卫', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '懿公弟申，谥戴公，狄乱中即位仅数日即卒，卫国几近亡国，为极短祚之君，事见《史记》本国世家记载。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/卫戴公"}]'::jsonb, '戴公', NULL, '卫戴公')
