VALUES ('weiguo-r20', '毁', 'wei-weiguo', ARRAY[]::text[], '姬', '卫', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '戴公弟毁，谥文公，狄乱后自齐归国立国，修政理民，使卫国得以复存，在位二十五年，事见《史记》本国世家记载。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/卫文公"}]'::jsonb, '文公', NULL, '卫文公')
