VALUES ('weiguo-r22', '瑕', 'wei-weiguo', ARRAY[]::text[], '姬', '卫', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '成公弟瑕，未得谥号，晋助成公复位期间立之，在位仅一年即为成公所复，史称卫君瑕，事见《史记》本国世家记载。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/君瑕"}]'::jsonb, NULL, NULL, '君瑕')
