VALUES ('weiguo-r23', '遫', 'wei-weiguo', ARRAY[]::text[], '姬', '卫', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '成公之子遫，谥穆公，在位十一年，承续文公以来复国之局，事迹记载有限，事见《史记》本国世家记载。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/卫穆公"}]'::jsonb, '穆公', NULL, '卫穆公')
