VALUES ('weiguo-r24', '臧', 'wei-weiguo', ARRAY[]::text[], '姬', '卫', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '穆公之子臧，谥定公，在位十二年，春秋中期卫国君主，除世次外史料疏略，事见《史记》本国世家记载。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/卫定公"}]'::jsonb, '定公', NULL, '卫定公')
