VALUES ('weiguo-r25', '衎', 'wei-weiguo', ARRAY[]::text[], '姬', '卫', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '定公之子衎，谥献公，孙林父、宁殖作乱，一度出奔，后复位，前后两段子在位，事见《史记》本国世家记载。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/卫献公"}]'::jsonb, '献公', NULL, '卫献公')
