VALUES ('weiguo-r26', '秋', 'wei-weiguo', ARRAY[]::text[], '姬', '卫', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '献公出奔期间，孙林父立弟秋，谥殇公，在位十二年，献公后赖晋复位，事见《史记》本国世家记载。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/卫殇公"}]'::jsonb, '殇公', NULL, '卫殇公')
