VALUES ('weiguo-r28', '恶', 'wei-weiguo', ARRAY[]::text[], '姬', '卫', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '献公之子恶，谥襄公，在位九年，承续献公复位后的政局，事迹记载有限，事见《史记》本国世家记载。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/卫襄公"}]'::jsonb, '襄公', NULL, '卫襄公')
