VALUES ('weiguo-r29', '元', 'wei-weiguo', ARRAY[]::text[], '姬', '卫', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '襄公之子元，谥灵公，在位四十二年，夫人南子执政，孔子曾见之，拒立嫡子蒯聵，事见《史记》本国世家记载。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/卫灵公"}]'::jsonb, '灵公', NULL, '卫灵公')
