VALUES ('weiguo-r30', '辄', 'wei-weiguo', ARRAY[]::text[], '姬', '卫', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '灵公孙辄，谥出公，灵公拒立父蒯聵而立辄，引发父子争国，前后两段子在位，事见《史记》本国世家记载。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/卫出公"}]'::jsonb, '出公', NULL, '卫出公')
