VALUES ('weiguo-r31', '蒯聩', 'wei-weiguo', ARRAY[]::text[], '姬', '卫', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '灵公嫡子蒯聵，谥庄公，因得罪南子出奔，赖晋、赵氏返国夺位，在位仅两年，事见《史记》本国世家记载。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/卫庄公"}]'::jsonb, '庄公', NULL, '卫庄公')
