VALUES ('weiguo-r32', '斑师', 'wei-weiguo', ARRAY[]::text[], '姬', '卫', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '庄公之子斑师，未得谥号，庄公卒后继位，旋即为卫君起所弑，在位仅数月，事见《史记》本国世家记载。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/斑师"}]'::jsonb, NULL, NULL, '斑师')
