VALUES ('weiguo-r33', '起', 'wei-weiguo', ARRAY[]::text[], '姬', '卫', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '灵公后裔起，未得谥号，弑斑师自立，在位仅一年即为出公辄所杀，事见《史记》本国世家记载。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/君起"}]'::jsonb, NULL, NULL, '君起')
