VALUES ('weiguo-r35', '黔', 'wei-weiguo', ARRAY[]::text[], '姬', '卫', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '出公之叔黔，谥悼公，在位五年，出公辄被逐后即位，事迹除世次外记载有限，事见《史记》本国世家记载。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/卫悼公"}]'::jsonb, '悼公', NULL, '卫悼公')
