VALUES ('weiguo-r36', '弗', 'wei-weiguo', ARRAY[]::text[], '姬', '卫', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '悼公之子弗，谥敬公，在位三十三年，战国初卫国君主，国势已衰，事迹疏略，事见《史记》本国世家记载。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/卫敬公"}]'::jsonb, '敬公', NULL, '卫敬公')
