VALUES ('weiguo-r37', '纠', 'wei-weiguo', ARRAY[]::text[], '姬', '卫', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '敬公之子纠，谥昭公，在位六年，旋即为叔怀公所弑，卫国再度因篡弑更迭，事见《史记》本国世家记载。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/卫昭公"}]'::jsonb, '昭公', NULL, '卫昭公')
