VALUES ('weiguo-r38', '亶', 'wei-weiguo', ARRAY[]::text[], '姬', '卫', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '昭公之叔亶，弑侄自立，谥怀公，在位十一年，为战国早期卫国篡弑之例，事见《史记》本国世家记载。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/卫怀公"}]'::jsonb, '怀公', NULL, '卫怀公')
