VALUES ('weiguo-r39', '颓', 'wei-weiguo', ARRAY[]::text[], '姬', '卫', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '怀公之子颓，谥慎公，在位三十二年，战国中期卫国君主，国势卑微，事见《史记》本国世家记载。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/卫慎公"}]'::jsonb, '慎公', NULL, '卫慎公')
